import os, json, time, math
import numpy as np

N = 26
SNAP_CENTERS = 'storage/noesis/latest_centers.txt'
SNAP_RADII   = 'storage/noesis/latest_radii.txt'
OUT_DIR      = 'storage/noesis/nmap/results'
FREEZE_DIR   = 'storage/noesis/nmap/freezes'

K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]

def load_snapshot():
  if os.path.exists(SNAP_CENTERS) and os.path.exists(SNAP_RADII):
    c = np.loadtxt(SNAP_CENTERS, dtype=float).reshape(N,2)
    r = np.loadtxt(SNAP_RADII, dtype=float).reshape(N,)
    return c, r
  # Fallback: conservative grid+hole feasible layout
  centers = []
  radius = 0.08
  for i in range(5):
    for j in range(6):
      if len(centers) < 26:
        x = 0.1 + i*0.2
        y = 0.1 + j*0.15
        centers.append([x, y])
  c = np.array(centers, dtype=float)
  r = np.full(N, radius, dtype=float)
  return c, r

def slacks(c, r):
  x = c[:,0]; y = c[:,1]
  s_xL = x - r
  s_xR = 1.0 - x - r
  s_yB = y - r
  s_yT = 1.0 - y - r
  diff = c[:,None,:] - c[None,:,:]
  dist = np.sqrt(np.sum(diff**2, axis=2))
  s_pairs = dist - (r[:,None] + r[None,:])
  return (s_xL, s_xR, s_yB, s_yT), s_pairs

def boundary_mask(c, r, tol):
  (s_xL, s_xR, s_yB, s_yT), _ = slacks(c, r)
  return (s_xL <= tol) | (s_xR <= tol) | (s_yB <= tol) | (s_yT <= tol)

def topk_slack_interior(c, r, tol, K):
  (_, _, _, _), sp = slacks(c, r)
  bmask = boundary_mask(c, r, tol)
  triples = []
  for i in range(N):
    for j in range(i+1, N):
      if bmask[i] or bmask[j]:
        continue
      triples.append((i, j, float(sp[i,j])))
  triples.sort(key=lambda t: t[2])
  return [(i,j) for (i,j,_) in triples[:K]]

# Grad rows
def grad_row_boundary(i, kind):
  row = np.zeros(3*N, dtype=float)
  xi = 3*i; yi = xi+1; ri = xi+2
  if kind in ('xL','x_min'):
    row[xi] = 1.0;  row[ri] = -1.0
  elif kind in ('xR','x_max'):
    row[xi] = -1.0; row[ri] = -1.0
  elif kind in ('yB','y_min'):
    row[yi] = 1.0;  row[ri] = -1.0
  elif kind in ('yT','y_max'):
    row[yi] = -1.0; row[ri] = -1.0
  return row

def grad_row_pair(c, i, j):
  row = np.zeros(3*N, dtype=float)
  xi = 3*i; yi = xi+1; ri = xi+2
  xj = 3*j; yj = xj+1; rj = xj+2
  dx = c[i,0] - c[j,0]; dy = c[i,1] - c[j,1]
  d = float(np.hypot(dx, dy))
  if d > 1e-15:
    invd = 1.0/d
    row[xi] = dx*invd; row[yi] = dy*invd
    row[xj] = -dx*invd; row[yj] = -dy*invd
  row[ri] = -1.0; row[rj] = -1.0
  return row

def kkt_proxy_pairs(c, r, tol):
  # Build active sets
  (s_xL, s_xR, s_yB, s_yT), sp = slacks(c, r)
  b_rows = []
  for i in range(N):
    if s_xL[i] <= tol: b_rows.append(('b', i, 'xL'))
    if s_xR[i] <= tol: b_rows.append(('b', i, 'xR'))
    if s_yB[i] <= tol: b_rows.append(('b', i, 'yB'))
    if s_yT[i] <= tol: b_rows.append(('b', i, 'yT'))
  p_rows = []
  for i in range(N):
    for j in range(i+1, N):
      if sp[i,j] <= tol:
        p_rows.append(('p', i, j))

  if not b_rows and not p_rows:
    return {}, b_rows, p_rows

  rows = []
  tags = []
  for (_, i, kind) in b_rows:
    rows.append(grad_row_boundary(i, kind)); tags.append(('b',i,kind))
  for (_, i, j) in p_rows:
    rows.append(grad_row_pair(c, i, j)); tags.append(('p',i,j))

  J = np.vstack(rows)                 # (#cons, 3N)
  A = J.T                             # (3N, #cons)
  e_r = np.zeros(3*N, dtype=float); e_r[2::3] = 1.0

  # Least-squares proxy with non-negativity by clipping
  lam, *_ = np.linalg.lstsq(A, e_r, rcond=None)
  lam = np.maximum(lam, 0.0)

  lam_pairs = {}
  for idx, tag in enumerate(tags):
    if tag[0] == 'p':
      i, j = int(tag[1]), int(tag[2])
      lam_pairs[(i,j)] = float(lam[idx])
  return lam_pairs, b_rows, p_rows

def topk_kkt_interior(c, r, tol, K):
  bmask = boundary_mask(c, r, tol)
  lam_pairs, _, _ = kkt_proxy_pairs(c, r, tol)
  # Build list only over interior pairs (both discs not boundary-active)
  entries = []
  for (i,j), lam in lam_pairs.items():
    if bmask[i] or bmask[j]:
      continue
    entries.append((i,j,lam))
  # Sort by descending lambda (higher “load” first)
  entries.sort(key=lambda t: t[2], reverse=True)
  return [(i,j) for (i,j,_) in entries[:K]]

def jaccard(a, b):
  A = set(a); B = set(b)
  if not A and not B: return 1.0
  if not A or not B:  return 0.0
  inter = len(A & B); uni = len(A | B)
  return inter/uni if uni>0 else 1.0

def compute_overlap(c, r):
  result = {}
  for tol in TOLS:
    result[str(tol)] = {}
    for K in K_GRID:
      top_slack = topk_slack_interior(c, r, tol, K)
      top_kkt   = topk_kkt_interior(c, r, tol, K)
      J = jaccard(top_slack, top_kkt)
      result[str(tol)][str(K)] = {
        'slack_topk': top_slack,
        'kkt_topk': top_kkt,
        'jaccard_slack_vs_kkt': J
      }
  # Summaries per tol
  summary = {}
  for tol in TOLS:
    vals = [result[str(tol)][str(K)]['jaccard_slack_vs_kkt'] for K in K_GRID]
    summary[str(tol)] = {
      'mean_jaccard': float(np.mean(vals)) if len(vals)>0 else None,
      'min_jaccard': float(np.min(vals)) if len(vals)>0 else None,
      'max_jaccard': float(np.max(vals)) if len(vals)>0 else None
    }
  return result, summary

def write_json(path, obj):
  os.makedirs(os.path.dirname(path), exist_ok=True)
  with open(path, 'w') as f:
    json.dump(obj, f, indent=2)

def construct_packing():
  c0, r0 = load_snapshot()
  overlap, summary = compute_overlap(c0, r0)
  now = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
  report = {
    'generated_at': now,
    'snapshot_sum_radii': float(np.sum(r0)),
    'k_grid': K_GRID,
    'tols': TOLS,
    'overlap': overlap,
    'summary': summary
  }
  out_path = os.path.join(OUT_DIR, 'noesis_internal_cross_method_topk_overlap.json')
  freeze_path = os.path.join(FREEZE_DIR, f'noesis_internal_cross_method_topk_overlap_{now}.json')
  write_json(out_path, report)
  write_json(freeze_path, report)

  # Console summary
  print("EXEC_LOG: Cross-method Top-K overlap")
  for tol in TOLS:
    s = summary[str(tol)]
    print(f"tol={tol} meanJ={s['mean_jaccard']:.4f} minJ={s['min_jaccard']:.4f} maxJ={s['max_jaccard']:.4f}")

  # Return baseline packing with tiny shrink
  r = np.maximum(r0 - 1e-9, 1e-12)
  return c0.astype(float), r.astype(float)
